private lemma zr_BackIs_seq {n : ℕ} {Γ S₁ S₂ J : Type} {x : List Γ} [DecidableEq S₁]
    {M₁ : MultiTapeTM n Γ S₁} {M₂ : MultiTapeTM n Γ S₂} {e₁ d₁ : S₁} {e₂ : S₂}
    {X₂ : Set (Option S₂)} {C₁ : Contract M₁ e₁ {some d₁} J x} {C₂ : Contract M₂ e₂ X₂ J x}
