    {e₂ : S₂} {X₂ : Set (Option S₂)} (he : a₁ ≠ a₂) {C₀ : Contract M₀ e₀ {some a₁, some a₂} J x}
    {C₂ : Contract M₂ e₂ X₂ J x} {V : J → Prop} {v : J → Bool}
    {T₁ T₂ : J → Fin 2 → ℤ → Option (ZoneSym k)} {p₁ p₂ : J → Fin 2 → ℤ} {τ₀ τ₂ : J → ℕ}
    {L U : J → Fin 2 → ℤ} (h₀ : zr_PinStep C₀ V T₁ T₁ p₁ p₁ τ₀ L U)
