private lemma zr_peek_verdict {k : ℕ} {J : Type} {x : List (ZoneSym k)} {V : J → Prop}
    {i : Fin 2} {δ : SignType} {choose : Option (ZoneSym k) → Bool}
    {T : J → Fin 2 → ℤ → Option (ZoneSym k)} {p : J → Fin 2 → ℤ} {v : J → Bool}
