    {i : Fin 2} {δ : SignType} {choose : Option (ZoneSym k) → Bool}
    {T₁ T₂ : J → Fin 2 → ℤ → Option (ZoneSym k)} {p₁ p₂ : J → Fin 2 → ℤ} {τ₀ τ₂ : J → ℕ}
    {L U : J → Fin 2 → ℤ} {M₂ : MultiTapeTM 2 (ZoneSym k) S₂} {e₂ : S₂} {X₂ : Set (Option S₂)}
